begin;
set local search_path=public,extensions;
select plan(18);
set local role anon;
select ok(get_public_business('alpha-wellness-lab') is not null,'published organization is public');
select is(get_public_business('isolation-suspended-fixture'),null::jsonb,'suspended organization is rejected');
select is(get_public_business('missing-fixture'),null::jsonb,'unknown organization is rejected generically');
select is(jsonb_array_length(get_public_business('alpha-wellness-lab')->'services'),2,'only active public assigned services are visible');
select ok(not(get_public_business('alpha-wellness-lab') ?| array['id','email','phone','memberships','settings','availability']),'private organization fields are absent');
select ok(not((get_public_business('alpha-wellness-lab')->'services'->0) ?| array['organizationId','staffIds']),'internal relationships are absent from discovery');
select is(jsonb_array_length(get_public_availability_context('alpha-wellness-lab','12000000-0000-4000-8000-000000000101',null,'2026-09-07','2026-08-19T00:00:00Z')->'staff'),2,'any-staff context includes eligible assigned members');
select is(jsonb_array_length(get_public_availability_context('alpha-wellness-lab','12000000-0000-4000-8000-000000000101','13000000-0000-4000-8000-000000000102','2026-09-07','2026-08-19T00:00:00Z')->'staff'),1,'specific staff context is bounded');
select is(get_public_availability_context('alpha-wellness-lab','23000000-0000-4000-8000-000000000201',null,'2026-09-07','2026-08-19T00:00:00Z'),null::jsonb,'cross-organization service is rejected');
select is(get_public_availability_context('alpha-wellness-lab','12000000-0000-4000-8000-000000000101','24000000-0000-4000-8000-000000000202','2026-09-07','2026-08-19T00:00:00Z'),null::jsonb,'cross-organization staff is rejected');
select is(get_public_availability_context('isolation-suspended-fixture','34000000-0000-4000-8000-000000000301',null,'2026-09-09','2026-08-19T00:00:00Z'),null::jsonb,'suspended availability is rejected');
select ok(jsonb_array_length(get_public_availability_context('alpha-wellness-lab','12000000-0000-4000-8000-000000000101',null,'2026-09-07','2026-08-19T00:00:00Z')->'windows')>0,'weekly windows are returned for the requested weekday');
select is(jsonb_array_length(get_public_availability_context('alpha-wellness-lab','12000000-0000-4000-8000-000000000101',null,'2026-09-08','2026-08-19T00:00:00Z')->'windows'),0,'a day without recurring hours has no windows');
select ok(jsonb_array_length(get_public_availability_context('alpha-wellness-lab','12000000-0000-4000-8000-000000000101',null,'2026-09-07','2026-08-19T00:00:00Z')->'occupied')>=3,'blocks, appointments, and live holds occupy time');
select ok(not((get_public_availability_context('alpha-wellness-lab','12000000-0000-4000-8000-000000000101',null,'2026-09-07','2026-08-19T00:00:00Z')->'occupied'->0) ?| array['reason','appointmentId','clientId','kind']),'occupied intervals contain no private detail');
select ok((select relrowsecurity from pg_class where oid='public.appointments'::regclass),'appointment RLS is enabled');
select ok((select relrowsecurity from pg_class where oid='public.booking_holds'::regclass),'hold RLS is enabled');
select throws_ok($$select * from public.appointments$$,'42501',null,'anonymous cannot read appointment rows directly');
select * from finish();rollback;
